/**
 * Pictures of the report itself, shown once a puzzle is over: the lines of the
 * company's own income statement that clues 1 and 2 came from, as the annual
 * report prints them, latest year only, with those lines highlighted.
 *
 * The list is generated by scripts/daily-puzzle/excerpts.puzzle.ts into
 * data/daily-puzzle/excerpts.ts. Rules (excerpts.test.ts enforces the first four):
 * - Every highlighted figure is recorded as printed and must equal the puzzle's
 *   own figure in the statement's units. A picture paired with the wrong puzzle,
 *   or a puzzle whose numbers changed, fails the test. Where the caption shows a
 *   subtraction, it is rechecked from the printed figures.
 * - File names are a hash of the picture, never the puzzle number or the
 *   company: these files are public, and a guessable name would let anyone open
 *   a future puzzle's answer before its day.
 * - Width and height are the file's own, so the page reserves the right space.
 * - Only the server reads this list (through lib/daily-puzzle/catalog.ts); a page
 *   sends the browser the one excerpt for the puzzle it shows.
 * - Each part is one continuous cut of the filing; the lines left out between
 *   them are counted and said on the page, in the page's own type.
 * - Source: the filing on EDGAR. The SEC states that EDGAR public filing content
 *   is free to access and reuse.
 */
import { EXCERPTS } from "@/data/daily-puzzle/excerpts";

export type ExcerptPart = {
  /** Under /public. */
  src: string;
  /** In pixels, captured at twice the size it is laid out at (340px), so it is never shown wider than half this. */
  width: number;
  height: number;
  /** First and last rows in this part, for the alt text. */
  from: string;
  to: string;
};

export type PrintedLine = { label: string; printed: string };

export type ReportExcerptRecord = {
  /** The statement's title in lower case, as the report names it; absent when the figures sit in a note table instead. */
  statement?: string;
  /** The units line the statement prints, which the caption repeats. */
  units: "thousands" | "millions";
  parts: ExcerptPart[];
  /** The highlighted rows: label and figure as printed, and the clue each backs. */
  shows: (PrintedLine & { clue: "revenue" | "margin" })[];
  /** The cost line that, taken from revenue, leaves operating profit, where the statement has one. */
  costs?: PrintedLine;
  /** Lines of the statement between the two parts that are not shown. */
  leftOut: number;
};

export type ReportExcerpt = ReportExcerptRecord;

export function excerptFor(number: number): ReportExcerpt | undefined {
  return EXCERPTS[number];
}

export function excerptNumbers(): number[] {
  return Object.keys(EXCERPTS).map(Number);
}

export const DIVISOR: Record<ReportExcerptRecord["units"], number> = { thousands: 1e3, millions: 1e6 };

/** "11,925,601" -> 11925601; "(4,512)" -> -4512. */
export function printedNumber(printed: string): number {
  const negative = /^\(.*\)$/.test(printed.trim()) || printed.trim().startsWith("-");
  const value = Number(printed.replace(/[^\d.]/g, ""));
  return negative ? -value : value;
}
